import React from 'react';
import Header from './components/Header';
import Hero from './components/Hero';
import Destinations from './components/Destinations';
import Hotels from './components/Hotels';

function App() {
  const destinations = [
    { name: 'New York City', image: 'C:\Users\nishi\Downloads\SST6941\travel-website\public\images\destination-1.jpg', description: 'Visit the city that never sleeps.' },
    { name: 'Paris', image: '/images/destination-2.jpg', description: 'Experience the romance of the city.' },
    { name: 'Tokyo', image: '/images/destination-3.jpg', description: 'Explore Tokyo’s vibrant culture.' }
  ];

  return (
    <div>
      <Header />
      <Hero />
      <Destinations title="Popular Destinations" items={destinations} />
      <Hotels />
    </div>
  );
}

export default App;
